mapper.select:
SELECT oi.order_no, -- 订单基础分类信息 oi.parent_type, oi.sub_type, -- 订单需求备注 大厅正常展示 oi.remark, -- 价格相关信息 oi.goods_budget, oi.reward_price, oi.order_price, -- 时间与状态 oi.expect_time, oi.order_status, oi.create_time, -- 完整展示出发地址 sa.address AS startAddress, -- 完整展示目的地址 ea.address AS endAddress FROM order_info oi -- 关联出发地址表 LEFT JOIN user_address sa ON oi.start_address_id = sa.id -- 关联目的地址表 LEFT JOIN user_address ea ON oi.end_address_id = ea.id WHERE -- 条件1：订单状态为待接单 oi.order_status = 0 -- 条件2：排除已删除订单 AND oi.is_deleted = 0 -- 条件3：过滤已超时失效订单
-- 动态筛选：一级订单类型
AND oi.parent_type = #{query.parentType}
-- 动态筛选：二级细分订单类型
AND oi.sub_type = #{query.subType}
ORDER BY ${query.sortField} ${query.sortOrder}
ORDER BY oi.create_time DESC

mapper.update:
UPDATE order_info
SET is_deleted = 1
WHERE id = #{id}

mapper.select:
SELECT
oi.*,
sa.address AS startAddressText,
ea.address AS endAddressText
FROM order_info oi
LEFT JOIN user_address sa ON oi.start_address_id = sa.id
LEFT JOIN user_address ea ON oi.end_address_id = ea.id

    oi.is_deleted = 0



        AND oi.expect_time > NOW()




        AND oi.user_id = #{userId}




        AND oi.rider_id = #{riderId}




        AND oi.parent_type = #{parentType}


        AND oi.sub_type = #{subType}


        AND oi.reward_price = #{rewardPrice}


        AND oi.pay_status = #{payStatus}


        AND oi.order_status = #{orderStatus}


ORDER BY oi.create_time DESC
